<?php

declare(strict_types=1);

namespace Architex\Platform\Documents;

use Architex\Platform\Audit\AuditService;
use Architex\Platform\Identity\Identifier;
use Architex\Platform\Project\ProjectContext;
use Architex\Platform\Project\ProjectPhase;
use Architex\Platform\Records\ProjectRecordService;
use PDO;
use Throwable;

final readonly class DocumentService
{
    private const TYPES=['drawing','specification','appointment','approval_letter','municipal_form','submission_pack','tender_pack','rfi','site_instruction','payment_certificate','closeout_certificate','warranty','closeout_pack'];
    private const DISCIPLINES=['architectural','structural','civil','electrical','mechanical','fire','quantity_surveying','general'];
    private const PHASES=['onboarding','feasibility','appointment','concept_design','design_development','municipal_submission','tender_procurement','construction_execution','closeout'];
    private const PURPOSES=['for_review','for_information','for_municipal_submission','for_tender','for_construction','as_built','closeout'];
    private const SHEETS=['site_plan','floor_plan','section','elevation','detail','schedule','cover','general'];

    public function __construct(private PDO $pdo){}

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function create(string $organisationId,string $userId,string $role,array $input):array
    {
        $this->writer($organisationId,$userId,$role);$projectId=$this->id($input['projectId']??null,'document_project_required');$project=$this->project($organisationId,$projectId);
        $documentId=Identifier::generate();$revisionId=Identifier::generate();$title=$this->text($input['title']??null,220,'document_title_required');$type=$this->choice($input['documentType']??null,self::TYPES,'document_type_invalid');$discipline=$this->choice($input['discipline']??null,self::DISCIPLINES,'document_discipline_invalid');$phase=$this->choice($input['phase']??$project['currentPhase'],self::PHASES,'document_phase_invalid');$purpose=$this->choice($input['issuePurpose']??null,self::PURPOSES,'document_issue_purpose_invalid');$code=$this->text($input['revisionCode']??null,40,'document_revision_code_required');$notes=$this->optionalText($input['notes']??'',12000,'document_notes_invalid');$fileId=$this->file($organisationId,$projectId,$input['fileId']??null);$authorRole=$this->optionalText($input['authorRole']??$project['leadProfessionalRole'],60,'document_author_role_invalid');$reviewerRole=$this->optionalText($input['reviewerRole']??$project['leadProfessionalRole'],60,'document_reviewer_role_invalid');$drawing=$this->drawing($type,$input['drawing']??null,$title,$discipline,$purpose);
        $this->transaction(function()use($documentId,$revisionId,$organisationId,$projectId,$title,$type,$discipline,$phase,$authorRole,$reviewerRole,$userId,$code,$purpose,$fileId,$notes,$drawing):void{
            $this->pdo->prepare('INSERT INTO controlled_documents(id,organisation_id,project_id,title,document_type,discipline,phase,author_role,reviewer_role,current_revision_id,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),:title,:type,:discipline,:phase,:author_role,:reviewer_role,UNHEX(:revision_id),UNHEX(:user_id))')->execute(['id'=>$documentId,'organisation_id'=>$organisationId,'project_id'=>$projectId,'title'=>$title,'type'=>$type,'discipline'=>$discipline,'phase'=>$phase,'author_role'=>$authorRole,'reviewer_role'=>$reviewerRole,'revision_id'=>$revisionId,'user_id'=>$userId]);
            $this->insertRevision($revisionId,$organisationId,$projectId,$documentId,null,$code,'draft',$purpose,$fileId,$notes,null,$userId,$drawing,$title,$discipline);
            $this->audit($organisationId,$userId,'document.draft_created',$revisionId,['documentId'=>$documentId,'projectId'=>$projectId,'revisionCode'=>$code,'documentType'=>$type]);
        });return$this->get($organisationId,$userId,$revisionId);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function updateDraft(string $organisationId,string $userId,string $role,string $revisionId,array $input):array
    {
        $this->writer($organisationId,$userId,$role);$current=$this->get($organisationId,$userId,$revisionId);if($current['status']!=='draft')throw new DocumentException('document_not_draft');$notes=array_key_exists('notes',$input)?$this->optionalText($input['notes'],12000,'document_notes_invalid'):$current['notes'];$fileId=array_key_exists('fileId',$input)?$this->file($organisationId,$current['projectId'],$input['fileId']):$current['fileId'];$drawing=$current['drawing'];if($drawing!==null&&array_key_exists('drawing',$input))$drawing=$this->drawing('drawing',array_replace($drawing,is_array($input['drawing'])?$input['drawing']:[]),$current['title'],$current['discipline'],$current['issuePurpose']);
        $this->transaction(function()use($revisionId,$organisationId,$userId,$notes,$fileId,$drawing):void{$s=$this->pdo->prepare("UPDATE document_revisions SET notes=:notes,file_id=UNHEX(:file_id) WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id) AND status='draft'");$s->execute(['notes'=>$notes,'file_id'=>$fileId,'id'=>$revisionId,'organisation_id'=>$organisationId]);if($drawing!==null)$this->pdo->prepare("UPDATE drawing_register_entries SET drawing_number=:number,sheet_type=:sheet,scale_label=:scale WHERE revision_id=UNHEX(:id) AND status='draft'")->execute(['number'=>$drawing['drawingNumber'],'sheet'=>$drawing['sheetType'],'scale'=>$drawing['scale'],'id'=>$revisionId]);$this->audit($organisationId,$userId,'document.draft_updated',$revisionId,['fileId'=>$fileId,'drawing'=>$drawing]);});return$this->get($organisationId,$userId,$revisionId);
    }

    /** @return array<string,mixed> */
    public function submitForReview(string $organisationId,string $userId,string $role,string $revisionId,string $reason):array{return$this->transition($organisationId,$userId,$role,$revisionId,'draft','pending_review','review_reason','document.submitted_for_review',$this->requiredText($reason,500,'document_review_reason_required'));}

    /** @return array<string,mixed> */
    public function approve(string $organisationId,string $userId,string $role,string $revisionId,bool $humanConfirmed,string $reason):array
    {
        if(!$humanConfirmed)throw new DocumentException('document_approval_confirmation_required');$reason=$this->requiredText($reason,500,'document_approval_reason_required');$this->writer($organisationId,$userId,$role);$current=$this->get($organisationId,$userId,$revisionId);if($current['status']!=='pending_review')throw new DocumentException('document_not_reviewable');
        $this->transaction(function()use($organisationId,$userId,$revisionId,$reason):void{$s=$this->pdo->prepare("UPDATE document_revisions SET status='approved',approved_by=UNHEX(:user_id),approved_at=UTC_TIMESTAMP(6),approval_reason=:reason WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id) AND status='pending_review'");$s->execute(['user_id'=>$userId,'reason'=>$reason,'id'=>$revisionId,'organisation_id'=>$organisationId]);if($s->rowCount()!==1)throw new DocumentException('document_not_reviewable');$this->pdo->prepare("UPDATE drawing_register_entries SET status='approved' WHERE revision_id=UNHEX(:id) AND status='pending_review'")->execute(['id'=>$revisionId]);$this->audit($organisationId,$userId,'document.approved',$revisionId,['reason'=>$reason]);});return$this->get($organisationId,$userId,$revisionId);
    }

    /** @return array<string,mixed> */
    public function issue(string $organisationId,string $userId,string $role,string $revisionId,bool $humanConfirmed,string $reason,?string $issuePurpose=null):array
    {
        if(!$humanConfirmed)throw new DocumentException('document_issue_confirmation_required');$reason=$this->requiredText($reason,500,'document_issue_reason_required');$this->writer($organisationId,$userId,$role);$current=$this->get($organisationId,$userId,$revisionId);if($current['status']!=='approved')throw new DocumentException('document_not_approved');$purpose=$issuePurpose===null?$current['issuePurpose']:$this->choice($issuePurpose,self::PURPOSES,'document_issue_purpose_invalid');$hash=hash('sha256',$this->json(['revisionId'=>$revisionId,'documentId'=>$current['documentId'],'revisionCode'=>$current['revisionCode'],'title'=>$current['title'],'documentType'=>$current['documentType'],'discipline'=>$current['discipline'],'phase'=>$current['phase'],'issuePurpose'=>$purpose,'notes'=>$current['notes'],'fileId'=>$current['fileId'],'drawing'=>$current['drawing'],'approvedBy'=>$current['approvedBy'],'approvalReason'=>$current['approvalReason'],'issueReason'=>$reason]));
        $this->transaction(function()use($organisationId,$userId,$role,$revisionId,$reason,$purpose,$hash,$current):void{$s=$this->pdo->prepare("UPDATE document_revisions SET status='issued',issue_purpose=:purpose,issued_by=UNHEX(:user_id),issued_at=UTC_TIMESTAMP(6),issue_reason=:reason,audit_hash=:hash WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id) AND status='approved'");$s->execute(['purpose'=>$purpose,'user_id'=>$userId,'reason'=>$reason,'hash'=>$hash,'id'=>$revisionId,'organisation_id'=>$organisationId]);if($s->rowCount()!==1)throw new DocumentException('document_not_approved');$this->pdo->prepare("UPDATE drawing_register_entries SET status='issued',issue_purpose=:purpose WHERE revision_id=UNHEX(:id) AND status='approved'")->execute(['purpose'=>$purpose,'id'=>$revisionId]);$recordType=$this->recordType($current['documentType'],$current['drawing']!==null,$purpose);$recordId=(new ProjectRecordService($this->pdo))->issue(new ProjectContext($organisationId,$userId,$current['projectId'],$role),ProjectPhase::from($current['phase']),'documents',$recordType,$current['title'],'issued',['documentId'=>$current['documentId'],'revisionId'=>$revisionId,'revisionCode'=>$current['revisionCode'],'issuePurpose'=>$purpose,'auditHash'=>$hash,'drawing'=>$current['drawing']],['required'=>false],array_values(array_filter([$current['fileId']])));$this->audit($organisationId,$userId,'document.issued',$revisionId,['reason'=>$reason,'issuePurpose'=>$purpose,'auditHash'=>$hash,'projectRecordId'=>$recordId]);});return$this->get($organisationId,$userId,$revisionId);
    }

    /** @param array<string,mixed> $input @return array<string,mixed> */
    public function revise(string $organisationId,string $userId,string $role,string $revisionId,array $input):array
    {
        $this->writer($organisationId,$userId,$role);$source=$this->get($organisationId,$userId,$revisionId);if($source['status']!=='issued')throw new DocumentException('document_revision_source_invalid');$code=$this->requiredText($input['revisionCode']??null,40,'document_revision_code_required');$reason=$this->requiredText($input['reason']??null,500,'document_revision_reason_required');$notes=array_key_exists('notes',$input)?$this->optionalText($input['notes'],12000,'document_notes_invalid'):$source['notes'];$purpose=$this->choice($input['issuePurpose']??'for_review',self::PURPOSES,'document_issue_purpose_invalid');$fileId=array_key_exists('fileId',$input)?$this->file($organisationId,$source['projectId'],$input['fileId']):$source['fileId'];$drawing=$source['drawing']===null?null:$this->drawing('drawing',array_replace($source['drawing'],is_array($input['drawing']??null)?$input['drawing']:[]),$source['title'],$source['discipline'],$purpose);$newId=Identifier::generate();
        $this->transaction(function()use($organisationId,$userId,$source,$revisionId,$newId,$code,$purpose,$fileId,$notes,$reason,$drawing):void{$s=$this->pdo->prepare("UPDATE document_revisions SET status='superseded' WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id) AND status='issued'");$s->execute(['id'=>$revisionId,'organisation_id'=>$organisationId]);if($s->rowCount()!==1)throw new DocumentException('document_revision_source_invalid');$this->insertRevision($newId,$organisationId,$source['projectId'],$source['documentId'],$revisionId,$code,'draft',$purpose,$fileId,$notes,$reason,$userId,$drawing,$source['title'],$source['discipline']);$this->pdo->prepare('UPDATE controlled_documents SET current_revision_id=UNHEX(:new_id) WHERE id=UNHEX(:document_id) AND current_revision_id=UNHEX(:old_id)')->execute(['new_id'=>$newId,'document_id'=>$source['documentId'],'old_id'=>$revisionId]);$this->pdo->prepare("UPDATE drawing_register_entries SET status='superseded',superseded_by_revision_id=UNHEX(:new_id) WHERE revision_id=UNHEX(:old_id) AND status='issued'")->execute(['new_id'=>$newId,'old_id'=>$revisionId]);$this->audit($organisationId,$userId,'document.revised',$newId,['supersedes'=>$revisionId,'revisionCode'=>$code,'reason'=>$reason]);});return$this->get($organisationId,$userId,$newId);
    }

    /** @return array<string,mixed> */
    public function get(string $organisationId,string $userId,string $revisionId):array
    {
        $this->member($organisationId,$userId);$s=$this->pdo->prepare("SELECT LOWER(HEX(r.id)) id,LOWER(HEX(r.document_id)) documentId,LOWER(HEX(r.project_id)) projectId,LOWER(HEX(r.previous_revision_id)) previousRevisionId,r.revision_code revisionCode,r.status,r.issue_purpose issuePurpose,LOWER(HEX(r.file_id)) fileId,r.notes,r.revision_reason revisionReason,r.review_reason reviewReason,LOWER(HEX(r.approved_by)) approvedBy,r.approval_reason approvalReason,LOWER(HEX(r.issued_by)) issuedBy,r.issue_reason issueReason,r.audit_hash auditHash,DATE_FORMAT(r.created_at,'%Y-%m-%dT%H:%i:%s.%fZ') createdAt,d.title,d.document_type documentType,d.discipline,d.phase,d.author_role authorRole,d.reviewer_role reviewerRole FROM document_revisions r JOIN controlled_documents d ON d.id=r.document_id AND d.organisation_id=r.organisation_id WHERE r.id=UNHEX(:id) AND r.organisation_id=UNHEX(:organisation_id)");$s->execute(['id'=>$this->id($revisionId,'document_not_found'),'organisation_id'=>$organisationId]);$row=$s->fetch();if(!is_array($row))throw new DocumentException('document_not_found');$row['drawing']=$this->drawingRow($organisationId,$revisionId);return$row;
    }

    /** @return list<array<string,mixed>> */
    public function list(string $organisationId,string $userId,string $projectId):array
    {
        $this->member($organisationId,$userId);$projectId=$this->id($projectId,'document_project_invalid');$this->project($organisationId,$projectId);$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id FROM document_revisions WHERE organisation_id=UNHEX(:organisation_id) AND project_id=UNHEX(:project_id) ORDER BY created_at DESC,id');$s->execute(['organisation_id'=>$organisationId,'project_id'=>$projectId]);return array_map(fn(string$id):array=>$this->get($organisationId,$userId,$id),$s->fetchAll(PDO::FETCH_COLUMN));
    }

    /** @return array<string,mixed> */
    private function transition(string$o,string$u,string$r,string$id,string$from,string$to,string$column,string$event,string$reason):array{$this->writer($o,$u,$r);$current=$this->get($o,$u,$id);if($current['status']!==$from)throw new DocumentException('document_state_invalid');$this->transaction(function()use($o,$u,$id,$from,$to,$column,$event,$reason):void{$s=$this->pdo->prepare("UPDATE document_revisions SET status=:to,$column=:reason WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id) AND status=:from");$s->execute(['to'=>$to,'reason'=>$reason,'id'=>$id,'organisation_id'=>$o,'from'=>$from]);if($s->rowCount()!==1)throw new DocumentException('document_state_invalid');$this->pdo->prepare('UPDATE drawing_register_entries SET status=:to WHERE revision_id=UNHEX(:id) AND status=:from')->execute(['to'=>$to,'id'=>$id,'from'=>$from]);$this->audit($o,$u,$event,$id,['reason'=>$reason]);});return$this->get($o,$u,$id);}

    /** @param array<string,string>|null $drawing */
    private function insertRevision(string$id,string$o,string$p,string$d,?string$previous,string$code,string$status,string$purpose,?string$file,string$notes,?string$reason,string$user,?array$drawing,string$title,string$discipline):void{$this->pdo->prepare('INSERT INTO document_revisions(id,organisation_id,project_id,document_id,previous_revision_id,revision_code,status,issue_purpose,file_id,notes,revision_reason,created_by) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:document_id),UNHEX(:previous_id),:code,:status,:purpose,UNHEX(:file_id),:notes,:reason,UNHEX(:user_id))')->execute(['id'=>$id,'organisation_id'=>$o,'project_id'=>$p,'document_id'=>$d,'previous_id'=>$previous,'code'=>$code,'status'=>$status,'purpose'=>$purpose,'file_id'=>$file,'notes'=>$notes,'reason'=>$reason,'user_id'=>$user]);if($drawing!==null)$this->pdo->prepare('INSERT INTO drawing_register_entries(id,organisation_id,project_id,document_id,revision_id,drawing_number,title,discipline,sheet_type,scale_label,status,issue_purpose) VALUES(UNHEX(:id),UNHEX(:organisation_id),UNHEX(:project_id),UNHEX(:document_id),UNHEX(:revision_id),:number,:title,:discipline,:sheet,:scale,:status,:purpose)')->execute(['id'=>Identifier::generate(),'organisation_id'=>$o,'project_id'=>$p,'document_id'=>$d,'revision_id'=>$id,'number'=>$drawing['drawingNumber'],'title'=>$title,'discipline'=>$discipline,'sheet'=>$drawing['sheetType'],'scale'=>$drawing['scale'],'status'=>$status,'purpose'=>$purpose]);}
    /** @return array<string,string>|null */private function drawingRow(string$o,string$r):?array{$s=$this->pdo->prepare('SELECT drawing_number drawingNumber,title,discipline,sheet_type sheetType,scale_label scale,status,issue_purpose issuePurpose,LOWER(HEX(superseded_by_revision_id)) supersededByRevisionId FROM drawing_register_entries WHERE revision_id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$s->execute(['id'=>$r,'organisation_id'=>$o]);$row=$s->fetch();return is_array($row)?$row:null;}
    /** @return array<string,string>|null */private function drawing(string$type,mixed$v,string$title,string$discipline,string$purpose):?array{if($type!=='drawing'){if($v!==null)throw new DocumentException('document_drawing_not_allowed');return null;}if(!is_array($v))throw new DocumentException('document_drawing_required');return['drawingNumber'=>$this->requiredText($v['drawingNumber']??null,100,'document_drawing_number_required'),'title'=>$title,'discipline'=>$discipline,'sheetType'=>$this->choice($v['sheetType']??null,self::SHEETS,'document_sheet_type_invalid'),'scale'=>$this->nullableText($v['scale']??null,40,'document_scale_invalid')??'','status'=>'draft','issuePurpose'=>$purpose,'supersededByRevisionId'=>''];}
    /** @return array<string,string> */private function project(string$o,string$p):array{$s=$this->pdo->prepare('SELECT current_phase currentPhase,lead_professional_role leadProfessionalRole FROM projects WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id)');$s->execute(['id'=>$p,'organisation_id'=>$o]);$row=$s->fetch();if(!is_array($row))throw new DocumentException('document_project_not_found');return$row;}
    private function file(string$o,string$p,mixed$v):?string{if($v===null||$v==='')return null;$id=$this->id($v,'document_file_invalid');$s=$this->pdo->prepare("SELECT 1 FROM stored_files WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:organisation_id) AND project_id=UNHEX(:project_id) AND status='active'");$s->execute(['id'=>$id,'organisation_id'=>$o,'project_id'=>$p]);if($s->fetchColumn()===false)throw new DocumentException('document_file_not_found');return$id;}
    private function writer(string$o,string$u,string$r):void{if(!in_array($r,['owner','admin','member'],true))throw new DocumentException('document_permission_denied');$this->member($o,$u);}
    private function member(string$o,string$u):void{$s=$this->pdo->prepare("SELECT 1 FROM organisation_memberships WHERE organisation_id=UNHEX(:organisation_id) AND user_id=UNHEX(:user_id) AND status='active'");$s->execute(['organisation_id'=>$o,'user_id'=>$u]);if($s->fetchColumn()===false)throw new DocumentException('document_permission_denied');}
    private function recordType(string$type,bool$drawing,string$purpose):string{if($drawing)return$purpose==='for_construction'?'technical_drawings':'drawing_revision';return match($type){'submission_pack'=>'municipal_submission_pack','approval_letter'=>'municipal_approval_letter','tender_pack'=>'tender_pack','site_instruction'=>'site_instruction','rfi'=>'rfi','payment_certificate'=>'payment_certificate','closeout_pack'=>'closeout_pack',default=>'drawing_revision'};}
    private function audit(string$o,string$u,string$a,string$id,array$m):void{(new AuditService($this->pdo))->append($o,$u,$a,'document_revision',$id,$m);}
    private function transaction(callable$f):mixed{$this->pdo->beginTransaction();try{$v=$f();$this->pdo->commit();return$v;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
    private function id(mixed$v,string$r):string{if(!is_string($v)||preg_match('/\A[a-f0-9]{32}\z/i',$v)!==1)throw new DocumentException($r);return strtolower($v);}
    private function choice(mixed$v,array$a,string$r):string{if(!is_string($v)||!in_array($v,$a,true))throw new DocumentException($r);return$v;}
    private function text(mixed$v,int$m,string$r):string{return$this->requiredText($v,$m,$r);}
    private function requiredText(mixed$v,int$m,string$r):string{$v=is_string($v)?trim($v):'';if($v===''||mb_strlen($v)>$m)throw new DocumentException($r);return$v;}
    private function optionalText(mixed$v,int$m,string$r):string{$v=is_string($v)?trim($v):'';if(mb_strlen($v)>$m)throw new DocumentException($r);return$v;}
    private function nullableText(mixed$v,int$m,string$r):?string{if($v===null||$v==='')return null;return$this->requiredText($v,$m,$r);}
    private function json(array$v):string{return json_encode($v,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);}
}
